import fs from'node:fs';import cp from'node:child_process';import path from'node:path';import assert from'node:assert/strict';import{createHash}from'node:crypto';import{pathToFileURL}from'node:url';
const [root,out]=process.argv.slice(2),base='docs/healthroster-build/proposals/',sha=b=>createHash('sha256').update(b).digest('hex');
const blob=(rev,p)=>cp.execFileSync('git',['cat-file','blob',rev+':'+p],{cwd:root,maxBuffer:32e6});
const {functionEvents}=await import(pathToFileURL(path.join(root,base+'a0-current-root-install2-forward/PINNED_A0_CURRENT_SOURCE_INDEX.mjs')));
const packets=[['paid-match-legacy-retained-basis-consumer-20261015','3f3ff2401baf271face606ad2feef8a8bdea663d','retained-legacy-source.test.mjs',12],['paid-match-off-physical-contract-current-owner-20261015','c7b5cc496cac29e9680aa56892dfb24aa2b56ec1','join-source.test.mjs',8],['source-next-paid-purpose-current-consumer-20261015','1a7ad79f9c4e2796fe067a05c253e39bd07482c7','purpose-source.test.mjs',18]];
const read=(idx,f)=>blob(packets[idx][1],base+packets[idx][0]+'/'+f).toString();
function seal(){return packets.map(([dir,commit])=>{const p=base+dir+'/',raw=blob(commit,p+'FROZEN_ARTIFACT_MANIFEST.json'),m=JSON.parse(raw);for(const e of [...m.artifacts,{file:'FROZEN_ARTIFACT_MANIFEST.json'}]){const b=blob(commit,p+e.file);assert.deepEqual(b,fs.readFileSync(path.join(root,p+e.file)));if(e.sha256){assert.equal(b.length,e.bytes);assert.equal(sha(b),e.sha256);}}return{dir,commit,artifacts:m.artifacts.length+1,manifest_sha256:sha(raw)};});}
const before=seal();fs.mkdirSync(out,{recursive:true});
function reverse(s,hunks){for(const h of [...hunks].reverse()){assert.equal(s.split(h.after).length,2);s=s.replace(h.after,()=>h.before);}return s;}
const retained=JSON.parse(read(0,'COMPLETE_REVERSE_AND_INPUT_PINS.json'));const retainedBefore=reverse(read(0,'forward/01_complete_retained_transition_assert.sqlinc'),retained.hunks);assert.deepEqual(Buffer.from(retainedBefore),blob(retained.commit,retained.source));
const join=JSON.parse(read(1,'FULL_SOURCE_JOIN_PROOF.json'));assert.deepEqual(Buffer.from(reverse(read(1,'forward/01_complete_off_parent_scope.sqlinc'),join.hunks)),blob(join.commit,join.source));
const p=JSON.parse(read(2,'COMPLETE_CURRENT_EXTRACTION_AND_REVERSES.json'));const definition=s=>functionEvents(s).events.find(e=>e.kind==='CREATE').definition;
const nativeDefinition=functionEvents(blob(p.current,p.bank_input.file).toString()).events.find(e=>e.id==='public.bpay_next_source_paid_evidence_page_v1(jsonb)').definition;assert.equal(sha(nativeDefinition),p.bank_input.definition_sha256);
assert.equal(reverse(definition(read(2,p.public_wrapper.after_file)),p.public_wrapper.hunks),nativeDefinition);
let kernel=definition(read(2,p.kernel.file));kernel=kernel.replace(p.kernel.rename.after,()=>p.kernel.rename.before).replace('\n  -- Current physical permission',()=>p.kernel.removed_permissions[0]+'\n  -- Current physical permission').replace('\n  v_origin:=',()=>p.kernel.removed_permissions[1]+'\n  v_origin:=');assert.equal(kernel,nativeDefinition);
for(const k of ['purpose','facts']){const owner=p[k];assert.equal(reverse(read(2,owner.after_file),owner.hunks),read(2,owner.before_file));assert.equal(sha(read(2,owner.before_file)),owner.before_sha256);assert.deepEqual(Buffer.from(read(2,owner.before_file)),blob(p.own,owner.source));}
const tests=[];for(const [dir,commit,file,count]of packets){const r=cp.spawnSync(process.execPath,['--test','--test-reporter=tap',base+dir+'/'+file],{cwd:root,encoding:'utf8',maxBuffer:8e6});const b=Buffer.from(r.stdout+r.stderr);fs.writeFileSync(path.join(out,file+'.tap.txt'),b);assert.equal(r.status,0);assert.match(b.toString(),new RegExp('# pass '+count+'\\b'));assert.match(b.toString(),/# fail 0\b/);tests.push({dir,commit,cases:count,output_sha256:sha(b)});}
const result={source_only:true,native:false,mount_ready:false,before,after:seal(),tests,whole_reverses:6,unique_hunks_or_kernel_changes:12,complete_native_public_owner_reverse:true,actual_paid_cash_classification_unchanged:true,remaining:['complete final current shared-owner/native/security/financial/acceptance union','genuine NHSP magnitude/reversal/NONE companion path','ordinary Legacy withheld amount remains unproved']};fs.writeFileSync(path.join(out,'CHECKS.json'),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));
